<?php $editingSchedule = in_array($planAction, ['nuevo', 'editar'], true); ?>
<section class="panel <?= $editingSchedule ? 'form-section' : 'detail-panel' ?>">
<?php if ($editingSchedule): ?><div class="form-section-title"><span>04</span><div><h2>Cronograma</h2><p>Agrega entre 1 y 30 actividades. Fecha de Fin debe ser igual o posterior a Fecha de Inicio.</p></div></div><?php else: ?><h2>Cronograma</h2><?php endif; ?>
<div class="table-scroll"><table><caption class="sr-only">Actividades del cronograma</caption><thead><tr><th>Actividad</th><th>Fecha de Inicio</th><th>Fecha de Fin</th><?php if ($editingSchedule): ?><th>Fila</th><?php endif; ?></tr></thead><tbody data-plan-rows>
<?php foreach ($values['cronograma'] as $row): ?><tr><?php foreach (['actividad' => 'Actividad', 'fecha_inicio' => 'Fecha de Inicio', 'fecha_fin' => 'Fecha de Fin'] as $field => $label): ?><td class="wrap-cell"><?php if ($editingSchedule): ?><input data-plan-field="<?= e($field) ?>" data-label="<?= e($label) ?>" aria-label="<?= e($label) ?>" type="<?= $field === 'actividad' ? 'text' : 'date' ?>" <?= $field === 'actividad' ? 'maxlength="250"' : 'min="1000-01-01" max="9999-12-31"' ?> required value="<?= e($row[$field]) ?>"><?php else: ?><?= $field === 'actividad' ? e($row[$field]) : e((new DateTimeImmutable($row[$field]))->format('d/m/Y')) ?><?php endif; ?></td><?php endforeach; ?><?php if ($editingSchedule): ?><td><button class="button-secondary" type="button" data-plan-remove>Quitar</button></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>
<?php if ($editingSchedule): ?><button class="button-secondary" type="button" data-plan-add>+ Agregar actividad</button><p class="muted" id="plan-message" role="status" aria-live="polite"></p>
<template id="plan-row"><tr><td><input data-plan-field="actividad" data-label="Actividad" type="text" maxlength="250" required></td><td><input data-plan-field="fecha_inicio" data-label="Fecha de Inicio" type="date" min="1000-01-01" max="9999-12-31" required></td><td><input data-plan-field="fecha_fin" data-label="Fecha de Fin" type="date" min="1000-01-01" max="9999-12-31" required></td><td><button class="button-secondary" type="button" data-plan-remove>Quitar</button></td></tr></template>
<noscript><p class="alert alert-error">Activa JavaScript para agregar actividades y registrar el cronograma.</p></noscript><?php endif; ?></section>
